"""Read-only views composed from public contracts, reducers and frozen forecasts.

No world configuration, response evaluation, experiment execution or scalar reward
is accepted here. Original records are never repaired to make a comparison score.
"""
from __future__ import annotations

import copy
import hashlib
import math
from collections import Counter
from pathlib import Path

from ..contracts import canonical, digest, request_record, require_id
from ..evaluation import (
    MAGNETIC_QUANTITIES,
    NUMERICAL_QUANTITIES,
    measurement_definition_check,
    measurement_stage_check,
)
from ..measurements import density_archimedes, microscopy_specimen_observations
from ..scientific_checks import evaluate_fresh_predictions

PROFILE = "dense-public-v1"
UNITS = {**dict(zip(NUMERICAL_QUANTITIES, ("g/cm^3", "nm", "nm", "1", "1"), strict=True)),
         **dict(zip(MAGNETIC_QUANTITIES, ("kOe", "kGs", "MGOe"), strict=True))}


def verified_procedures():
    """A small frozen method inventory; no retrieval system or case-derived advice."""
    package = Path(__file__).resolve().parents[1]
    def reference(module, function):
        path = package / module
        return {"module": "ndfeb_sps." + module.removesuffix(".py"), "function": function,
                "source_sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    return {"version": "public-diagnostic-procedures-v1", "scope": "verified computation and record checks only; no scientific outcome recipe",
        "procedures": [
            {"id": "two-weighing-reduction-v1", "implementation": reference("measurements.py", "density_archimedes"),
             "use": "Inspect released inputs and recomputed density in inspect_feedback; raw artifact hashes remain in read_evidence/read_artifact.",
             "applicability": "Dry and immersed apparent masses in g; fluid density in g/cm^3; dry mass exceeds immersed mass.",
             "verification": "tests/test_measurements.py::test_archimedes_derivative_and_unknown_uncertainty",
             "failure_modes": ["Not an open-pore, wetting, suspension or air-buoyancy correction", "Input uncertainty propagation assumes independent standard uncertainties; absent uncertainty stays unknown", "Arithmetic agreement does not establish calibration"]},
            {"id": "field-feature-reduction-v1", "implementation": reference("measurements.py", "microscopy_specimen_observations"),
             "use": "Inspect raw field records and recomputed descriptors; preserve section, field, feature, population and threshold definitions.",
             "applicability": "Explicit feature sizes, scale and resolved-boundary metadata with declared coarse threshold and sampling plan.",
             "verification": "tests/test_measurements.py::test_microscopy_does_not_invent_grains",
             "failure_modes": ["Fields and features are not independently prepared bodies", "Selected 2D populations do not establish bulk 3D grains", "Unresolved boundaries do not become grains through numerical reduction"]},
            {"id": "frozen-target-comparison-v1", "implementation": reference("scientific_checks.py", "evaluate_fresh_predictions"),
             "use": "inspect_feedback joins immutable requested targets to released observations by request and specimen identity; inspect stage/unit/definition exclusions separately.",
             "applicability": "Authenticated frozen prediction, explicit target selection and released observations; diagnostic caller verifies record binding.",
             "verification": "tests/test_scientific_checks.py::test_exact_fresh_join_never_pools_same_temperature_previous_batch; tests/test_investigator_feedback.py",
             "failure_modes": ["A refitted prediction is not the committed forecast", "Omission, abstention and missing observations differ", "Scenario widths and specimen scatter do not imply Gaussian predictive uncertainty", "Later receipt time alone does not establish physical execution chronology"]},
        ]}


def _finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def selected_quantities(request, specimen):
    # Exactly the current conditional provider contract, not legacy aliases.
    return specimen.get("measurements", request.get("measurements", ["density_g_cm3"]))


def forecast_issues(prediction, request):
    """Collect independent schema and semantic issues without changing predictions."""
    errors, notes, targets = [], [], []
    if not isinstance(request, dict):
        return {"errors": ["forecast targets require an object request"], "notes": [], "targets": []}
    specimens = request.get("specimens", [])
    specimens = specimens if isinstance(specimens, list) else []
    rows = prediction.get("predictions") if isinstance(prediction, dict) else None
    if not isinstance(rows, list):
        return {"errors": ["forecast must contain predictions list"], "notes": [], "targets": []}
    by_id = {}
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            errors.append(f"predictions[{index}] must be an object")
            continue
        sid = row.get("specimen_id")
        if not isinstance(sid, str) or sid in by_id:
            errors.append(f"predictions[{index}] has missing or duplicate specimen_id")
            continue
        by_id[sid] = row
    expected = {s["specimen_id"] for s in specimens if isinstance(s, dict) and isinstance(s.get("specimen_id"), str)}
    if set(by_id) != expected:
        errors.append("forecast must cover each requested specimen exactly once")
    for specimen in specimens:
        if not isinstance(specimen, dict):
            continue
        sid = specimen.get("specimen_id")
        if not isinstance(sid, str):
            continue
        row = by_id.get(sid, {})
        selection = selected_quantities(request, specimen)
        selection = selection if isinstance(selection, list) else []
        endpoint = request.get("output_stage", "as_sintered")
        for quantity, unit in UNITS.items():
            item = row.get(quantity)
            requested = quantity in selection
            target = {"specimen_id": sid, "quantity": quantity, "requested": requested,
                      "request_endpoint": endpoint, "expected_unit": unit}
            if item is None:
                if requested:
                    target["forecast_state"] = "omitted"
                    notes.append(f"{sid}/{quantity}: requested forecast omitted, not an abstention")
                    targets.append(target)
                if quantity in ("density_g_cm3", "grain_size_nm"):
                    errors.append(f"{sid}/{quantity}: legacy model contract requires an object (null mean may abstain)")
                continue
            if not isinstance(item, dict):
                errors.append(f"{sid}/{quantity}: prediction must be object")
                continue
            prefix = f"{sid}/{quantity}"
            if item.get("unit") != unit:
                errors.append(prefix + f": expected unit {unit}")
            if not isinstance(item.get("status"), str) or not item["status"]:
                errors.append(prefix + ": explicit status required")
            for field in ("mean", "sd"):
                if field not in item or (item[field] is not None and (not _finite(item[field]) or item[field] < 0)):
                    errors.append(prefix + f": {field} must be finite nonnegative or null")
            if item.get("mean") is None:
                if item.get("sd") is not None:
                    errors.append(prefix + ": abstention cannot have numeric sd")
                if not item.get("reason"):
                    errors.append(prefix + ": abstention requires reason")
            elif item.get("status") in {"unsupported", "unavailable", "abstained"}:
                errors.append(prefix + ": numeric mean conflicts with abstention status")
            if unit == "1" and _finite(item.get("mean")) and item["mean"] > 1:
                errors.append(prefix + ": fraction mean exceeds one")
            if quantity == "coarse_number_fraction" and item.get("mean") is not None and (
                not _finite(item.get("coarse_threshold_nm")) or item["coarse_threshold_nm"] <= 0
            ):
                errors.append(prefix + ": positive coarse_threshold_nm required")
            stage = measurement_stage_check(item, {"measurement_stage": endpoint, "origin": request.get("origin")},
                                            forecast=row, specimen=specimen)
            if stage["reason"]:
                notes.append(prefix + ": " + stage["reason"])
            if not requested:
                notes.append(prefix + ": forecast supplied for an unrequested quantity")
            target.update(forecast_state="abstained" if item.get("mean") is None else "numeric",
                          prediction=copy.deepcopy(item), stage_compatibility=stage,
                          uncertainty_semantics=item.get("uncertainty_semantics", "undeclared"))
            targets.append(target)
    return {"errors": errors, "notes": notes, "targets": targets}


def _numeric_representation_equivalent(left, right):
    """Exact JSON structure/value equality allowing int/float representation only.

    Booleans remain distinct from numbers. No tolerance or missing-key inference.
    This classifies an error message; it never grants commitment acceptance.
    """
    if type(left) in (int, float) and type(right) in (int, float):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _numeric_representation_equivalent(left[key], right[key]) for key in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _numeric_representation_equivalent(a, b) for a, b in zip(left, right, strict=True))
    return left == right


def request_preview(request, state, sources):
    """Validate public syntax/history and disclose defaults; never call a plant."""
    errors, notes, effective = [], [], []
    if not isinstance(request, dict):
        return {"errors": ["request must be object"], "notes": [], "effective_specimens": []}
    try:
        canonical(request)
    except (ValueError, TypeError) as exc:
        errors.append(str(exc))
    for key in ("lot_id",):
        try:
            require_id(request.get(key), key)
        except ValueError as exc:
            errors.append(str(exc))
    if request.get("origin") not in ("synthetic", "physical"):
        errors.append("request.origin must be synthetic or physical")
    operation = request.get("operation", "manufacture")
    specimens = request.get("specimens", [])
    if not isinstance(specimens, list) or not specimens:
        errors.append("specimens must be nonempty list")
        specimens = []
    try:
        request_record(request)
    except (ValueError, TypeError, KeyError) as exc:
        errors.append(str(exc))
    preparations = request.get("preparations", [])
    c5_campaign = sources.get("task", {}).get("anneal_model_domain") == "c5-campaign-v1"
    c6_campaign = sources.get("task", {}).get("anneal_model_domain") == "c6-campaign-v1"
    c7_campaign = sources.get("task", {}).get("anneal_model_domain") == "c7-campaign-v1"
    magnetic = (c5_campaign or c6_campaign or c7_campaign
                or sources.get("task", {}).get("anneal_model_domain") == "magnetic-1b-v1")
    if isinstance(preparations, list) and not magnetic:
        expected_preparation = {"method": "sealed_quartz_degassing", "temperature_c": 600.,
            "hold_time_s": 900., "heating_rate_c_min": 5., "cooling_mode": "furnace_cooling"}
        for preparation in preparations:
            if (isinstance(preparation, dict) and isinstance(preparation.get("conditions"), dict)
                    and any(preparation["conditions"].get(k) != v for k, v in expected_preparation.items())):
                errors.append(f"{preparation.get('preparation_id')}: provider supports the accepted preparation only; changed preparation requires new model support")
    histories = {h["specimen"]["specimen_id"]: h for h in state.get("specimen_histories", [])}
    capabilities = sources.get("task", {}).get("measurement_capabilities", [])
    masses = []
    for index, specimen in enumerate(specimens):
        if not isinstance(specimen, dict):
            errors.append(f"specimens[{index}] must be object")
            continue
        sid = specimen.get("specimen_id", f"index:{index}")
        for key in ("specimen_id", "preparation_id", "cycle_id"):
            try:
                require_id(specimen.get(key), key)
            except ValueError as exc:
                errors.append(f"{sid}: {exc}")
        condition = specimen.get("conditions")
        if not isinstance(condition, dict):
            errors.append(f"{sid}: conditions must be object")
            continue
        # Existing validation explicitly accepts only public controls and no world.
        from ..models.workflow_response import validate_workflow_request_controls
        try:
            if c7_campaign:
                from ..models.c7_campaign import validate_c7_request_controls
                validate_c7_request_controls({**request, "specimens": [specimen]})
            elif c6_campaign:
                from ..models.c6_campaign import validate_c6_request_controls
                validate_c6_request_controls({**request, "specimens": [specimen]})
            elif c5_campaign:
                from ..models.c5_campaign import validate_c5_request_controls
                validate_c5_request_controls({**request, "specimens": [specimen]})
            elif magnetic:
                from ..models.magnetic_workflow import validate_magnetic_request_controls
                validate_magnetic_request_controls({**request, "specimens": [specimen]},
                                                   sources["task"].get("magnetic_domain"))
            else:
                validate_workflow_request_controls({**request, "specimens": [specimen]})
        except (ValueError, TypeError, KeyError) as exc:
            errors.append(f"{sid}: {exc}")
        if operation == "anneal" and sources.get("task", {}).get("anneal_model_domain") == "rpi-informed-v1":
            from ..models.conditional_workflow import validate_rpi_informed_anneal_domain
            try:
                validate_rpi_informed_anneal_domain(condition, input_stage=request.get("input_stage"),
                                                    output_stage=request.get("output_stage"))
            except (ValueError, TypeError, KeyError) as exc:
                errors.append(f"{sid}: {exc}")
        selection = selected_quantities(request, specimen)
        if not isinstance(selection, list) or not selection or not all(isinstance(q, str) for q in selection):
            errors.append(f"{sid}: measurements must be a nonempty list of quantity names")
            selection = []
        if len(selection) != len(set(selection)):
            errors.append(f"{sid}: duplicated measurements are unsupported")
        if "sps_log" in selection and operation != "manufacture":
            errors.append(f"{sid}: an existing-body operation cannot produce a new SPS trace")
        if "request_quantities" in request or "request_quantities" in specimen:
            notes.append(f"{sid}: request_quantities is not an executed selection; use measurements")
        if capabilities and any(q not in capabilities for q in selection):
            errors.append(f"{sid}: unsupported measurements {sorted(set(selection) - set(capabilities))}")
        context = condition.get("measurement_context", {})
        allowed_context = {"field_count", "features_per_field", "field_set_id", "selection", "coarse_threshold_nm"}
        if magnetic:
            allowed_context = allowed_context | {"piece_id"}
        if c7_campaign:   # C7 readings: density method, section surface, magnetometry normalization
            allowed_context = allowed_context | {"density_method", "surface", "normalization_density_g_cm3"}
        if not isinstance(context, dict) or set(context) - allowed_context:
            errors.append(f"{sid}: measurement_context only accepts public sampling choices {sorted(allowed_context)}")
        if isinstance(context, dict):
            for key, low, high in (("field_count", 1, 12), ("features_per_field", 2, 500)):
                if key in context:
                    value = context[key]
                    if not _finite(value) or not low <= value <= high:
                        errors.append(f"{sid}: measurement_context.{key} must be finite in [{low},{high}]")
                    elif value != int(value):
                        notes.append(f"{sid}: provider truncates measurement_context.{key} to {int(value)}; use an explicit integer for intended sampling")
            if "selection" in context and context["selection"] not in ("systematic_sections", "fine_region_only", "coarse_region_only"):
                errors.append(f"{sid}: unsupported microscopy selection")
            if "coarse_threshold_nm" in context and (not _finite(context["coarse_threshold_nm"]) or context["coarse_threshold_nm"] < 1):
                errors.append(f"{sid}: coarse_threshold_nm must be finite and >=1 nm")
        history = histories.get(sid)
        if operation == "manufacture" and history is not None:
            errors.append(f"{sid}: fresh manufacture requires a fresh specimen identity")
        if operation == "manufacture" and any(h["specimen"]["cycle_id"] == specimen.get("cycle_id") for h in histories.values()):
            errors.append(f"{sid}: existing manufacturing cycle cannot be reused for new manufacture")
        if any(h["specimen"]["preparation_id"] == specimen.get("preparation_id")
               and h["specimen"]["lot_id"] != request.get("lot_id") for h in histories.values()):
            errors.append(f"{sid}: existing preparation cannot change powder lot")
        if operation != "manufacture":
            if history is None:
                errors.append(f"{sid}: existing-body operation requires a known specimen")
            else:
                for key in ("preparation_id", "cycle_id"):
                    if specimen.get(key) != history["specimen"][key]:
                        errors.append(f"{sid}: {key} differs from original manufacturing identity")
                if history["specimen"]["lot_id"] != request.get("lot_id"):
                    errors.append(f"{sid}: lot differs from original manufacturing identity")
                if not history["reported_manufactured"] or not history["specimen_available"]:
                    errors.append(f"{sid}: released manufactured available body required")
                if request.get("input_stage") != history["current_stage"]:
                    errors.append(f"{sid}: input_stage differs from released current_stage")
                if "input_stage" in specimen and specimen["input_stage"] != request.get("input_stage"):
                    errors.append(f"{sid}: specimen.input_stage differs from requested/released input stage")
                if "prior_processing_conditions" in specimen:
                    supplied = specimen["prior_processing_conditions"]
                    authoritative = history["processing_history_conditions"]
                    # Match the existing commit predicate exactly. JavaScript can
                    # normalize 5.0 to 5, so Python equality alone is insufficient.
                    try:
                        history_matches = canonical(supplied) == canonical(authoritative)
                    except (ValueError, TypeError) as exc:
                        errors.append(f"{sid}: invalid prior_processing_conditions: {exc}")
                        history_matches = None
                    if history_matches is False:
                        if _numeric_representation_equivalent(supplied, authoritative):
                            errors.append(
                                f"{sid}: supplied prior_processing_conditions have a numeric representation "
                                "mismatch with released history (for example 5 versus 5.0); commitment "
                                "requires exact canonical JSON. Omit the optional prior_processing_conditions "
                                "field to let the controller bind authoritative released history before "
                                "forecast and commitment; preview again before submitting."
                            )
                        else:
                            errors.append(f"{sid}: supplied prior_processing_conditions differ from released history")
        controls = copy.deepcopy(condition)
        microscopy_selected = bool(set(selection) & {
            "grain_size_nm", "grain_d90_nm", "coarse_number_fraction", "porosity_area_fraction", "microstructure"})
        if microscopy_selected and isinstance(context, dict):
            # Public preview cannot inspect owner measurement settings. Show
            # unresolved selections explicitly rather than claim plant defaults.
            controls["measurement_context"] = {key: context.get(key) for key in sorted(allowed_context)}
            for key in ("field_count", "features_per_field"):
                value = controls["measurement_context"][key]
                if _finite(value) and value >= 0:
                    controls["measurement_context"][key] = int(value)
            if set(allowed_context) - set(context):
                notes.append(f"{sid}: unspecified microscopy sampling choices use provider settings; "
                             "null preview fields are unresolved here; delivered measurement_context and raw fields report actual sampling")
        mass = condition.get("mass_g", specimen.get("remaining_mass_g"))
        physical_existing = request.get("origin") == "physical" and operation != "manufacture"
        if physical_existing:
            # A proposed charge or provisional estimate is not measured inventory.
            # An existing-body measurement may establish mass; unknown availability
            # constrains its feasibility without inventing a material outcome.
            mass = history.get("remaining_mass_g") if history else None
            if mass is None:
                notes.append(f"{sid}: released remaining mass is unknown; supplied mass is an unverified proposal, not inventory; physical feasibility remains conditional")
        if history and operation != "manufacture" and history.get("remaining_mass_g") is not None:
            mass = history["remaining_mass_g"]
            if "remaining_mass_g" in specimen and specimen["remaining_mass_g"] != mass:
                errors.append(f"{sid}: specimen.remaining_mass_g differs from released remaining mass")
            if "mass_g" in condition and condition["mass_g"] != mass:
                errors.append(f"{sid}: conditions.mass_g differs from released remaining mass")
        if mass is not None and (not _finite(mass) or not 0 <= mass <= 25):
            errors.append(f"{sid}: mass_g must be finite in conditional range [0,25]")
        if "density_g_cm3" in selection and (not _finite(mass) or mass < .01):
            if not (physical_existing and mass is None):
                errors.append(f"{sid}: density needs known remaining mass >=0.01 g")
            else:
                notes.append(f"{sid}: density request may establish mass; obtain the raw weighings and method before interpreting the result")
        consumed = specimen.get("consumed_mass_g", 0)
        if physical_existing and mass is None and _finite(consumed) and consumed > 0:
            notes.append(f"{sid}: planned material consumption cannot be confirmed until usable remaining mass is measured")
        if not _finite(consumed) or consumed < 0 or (_finite(mass) and consumed > mass):
            errors.append(f"{sid}: consumed_mass_g must be nonnegative and within available mass")
        for key in ("destructive", "specimen_available"):
            if key in specimen and type(specimen[key]) is not bool:
                errors.append(f"{sid}: {key} must be boolean")
        if operation == "manufacture":
            for key, default in (("pressure_mpa", 60.), ("heating_rate_c_min", 10.), ("hold_time_s", 300.)):
                controls.setdefault(key, default)
            for key in ("temperature_c", "pressure_mpa", "heating_rate_c_min", "hold_time_s"):
                value = controls.get(key)
                if not _finite(value) or value < 0 or (key == "heating_rate_c_min" and value == 0):
                    errors.append(f"{sid}: {key} requires a finite valid process value")
            if _finite(controls.get("temperature_c")) and controls["temperature_c"] < 25:
                errors.append(f"{sid}: manufacture temperature must be >=25 C")
            if controls.get("cooling_mode", "furnace_cooling") not in ("furnace_cooling", "argon_quench"):
                errors.append(f"{sid}: cooling_mode must be furnace_cooling or argon_quench")
            if "sps_cooling_rate_c_min" in controls and (not _finite(controls["sps_cooling_rate_c_min"]) or controls["sps_cooling_rate_c_min"] <= 0):
                errors.append(f"{sid}: explicit SPS cooling rate must be finite and positive")
            if "sps_log" in selection:
                diameter = controls.get("diameter_mm", 10.)
                if not _finite(diameter) or not 1 <= diameter <= 50:
                    errors.append(f"{sid}: sps_log requires diameter_mm in [1,50]")
                if not _finite(mass):
                    errors.append(f"{sid}: sps_log requires known mass_g")
            if _finite(mass):
                masses.append(mass)
        if operation == "anneal" and "anneal_steps" not in controls:
            stages = ([] if request.get("input_stage") == "after_first_anneal" else ["after_first_anneal"])
            if request.get("output_stage") == "after_second_anneal":
                stages.append("after_second_anneal")
            controls["anneal_steps"] = [{"stage": stage, "temperature_c": 900. if stage == "after_first_anneal" else 520.,
                "hold_time_s": 7200., "heating_rate_c_min": 10., "pressure_mpa": 0.,
                "cooling_rate_c_min": None} for stage in stages]
            notes.append(f"{sid}: accepted default anneal shown; unspecified cooling rate is unresolved in public controls")
        effective.append({"specimen_id": sid, "operation": operation, "effective_controls": controls,
            "measurements": selection, "input_stage": request.get("input_stage"),
            "output_stage": request.get("output_stage", "as_sintered"),
            "released_current_stage": history["current_stage"] if history else None,
            "released_processing_history": history["processing_history_conditions"] if history else [],
            "available_mass_g": mass, "planned_consumed_mass_g": consumed,
            "forecast_targets": [{"quantity": q, "unit": UNITS.get(q, "mixed"),
                "measurement_stage": request.get("output_stage", "as_sintered")}
                for q in selection]})
    maximum = state.get("resources", {}).get("max_specimens")
    slots = state.get("resources", {}).get("specimens_requested", 0)
    if operation == "manufacture" and maximum is not None and slots + len(specimens) > maximum:
        errors.append("declared specimen request budget would be exceeded")
    return {"errors": list(dict.fromkeys(errors)), "notes": list(dict.fromkeys(notes)),
            "effective_specimens": effective, "new_manufacturing_slots": len(specimens) if operation == "manufacture" else 0,
            "known_nominal_new_mass_g": sum(masses), "new_bodies_without_mass": len(specimens)-len(masses) if operation == "manufacture" else 0,
            "physical_material_plan": copy.deepcopy(sources.get("task", {}).get("physical_material_plan", {})),
            "material_accounting_scope": "virtual exploration is separate from proposed physical allocation; release determines actual consumption"}


def public_diagnostics(record, observations):
    """Use fixed-target checks independently so one mismatch cannot hide the rest."""
    report = {"request_id": record["request_id"], "committed_at": record["committed_at"],
              "model_id": record["model_id"], "model_source_sha256": record["model_source_sha256"],
              "evidence_cutoff_ids": record.get("evidence_ids", []), "prospective_ref": record.get("prospective_ref"),
              "targets": [], "released_observation_ids": [], "diagnostic_errors": []}
    frozen_keys = ("request", "prediction", "request_id", "request_sha256", "model_id", "model_source_sha256",
                   "evidence_ids", "evidence_sha256", "committed_at")
    report["frozen_record_binding_verified"] = (digest({k: record[k] for k in frozen_keys}) == record.get("prospective_ref", {}).get("sha256")
                                                and digest(record["request"]) == record["request_sha256"])
    if not report["frozen_record_binding_verified"]:
        raise ValueError("frozen forecast record binding failed")
    rows = [r for r in observations if r.get("request_id") == record["request_id"]]
    report["released_observation_ids"] = [r["evidence_id"] for r in rows]
    forecasts = {r["specimen_id"]: r for r in record["prediction"]["predictions"]}
    for specimen in record["request"]["specimens"]:
        sid = specimen["specimen_id"]
        for quantity in selected_quantities(record["request"], specimen):
            matching = [r for r in rows if r.get("specimen_id") == sid and r.get("quantity") == quantity]
            item = forecasts.get(sid, {}).get(quantity)
            target = {"specimen_id": sid, "quantity": quantity, "frozen_prediction": copy.deepcopy(item),
                "forecast_state": "omitted" if item is None else "abstained" if item.get("mean") is None else "numeric",
                "measurement_state": "received" if matching else "missing_observation",
                "uncertainty_semantics": item.get("uncertainty_semantics", "undeclared") if item else None,
                "gaussian_calibration_claim": False, "observations": []}
            for obs in matching:
                details = {k: copy.deepcopy(obs[k]) for k in ("evidence_id", "origin", "unit", "status", "measurement_stage",
                    "method", "measurement_population", "measurement_statistic", "feature_definition", "sampling_plan",
                    "statistical_unit", "uncertainty", "uncertainty_basis", "inputs", "limits", "source_file", "source_sha256",
                    "forward_measurement_assumptions", "systematic_uncertainty", "delivered_conditions") if k in obs}
                if quantity in UNITS:
                    details["observed"] = obs.get("value")
                    details["stage_check"] = measurement_stage_check(item, obs, forecast=forecasts.get(sid), specimen=specimen)
                    details["definition_check"] = measurement_definition_check(item, obs, specimen=specimen)
                    details["unit_compatible"] = item is None or item.get("unit") == obs.get("unit")
                if quantity == "density_g_cm3" and isinstance(obs.get("inputs"), dict):
                    try:
                        reduced = density_archimedes(**obs["inputs"])
                        details["reduction_check"] = {"method": "density_archimedes", "recomputed": reduced["value"],
                            "reported": obs.get("value"), "difference": reduced["value"]-obs["value"] if _finite(obs.get("value")) else None}
                    except (ValueError, TypeError) as exc:
                        details["reduction_check"] = {"error": str(exc)}
                if quantity == "microstructure" and isinstance(obs.get("value"), dict):
                    raw = obs["value"].get("raw_field_records", [])
                    details["sampling"] = {"field_count": len(raw), "feature_count": sum(len(r.get("grain_sizes_nm", [])) for r in raw),
                        "sections": sorted({r.get("section_id", "unknown") for r in raw}),
                        "selection": obs["value"].get("selection"), "independent_specimens": 1,
                        "raw_records": "read_evidence or compute payload.evidence using this evidence_id",
                        "assumptions": obs["value"].get("measurement_assumptions")}
                    if raw:
                        try:
                            threshold = obs["value"].get("measurement_assumptions", {}).get("coarse_threshold_nm")
                            reduced = microscopy_specimen_observations(raw, coarse_threshold_nm=threshold)
                            details["recomputed_descriptors"] = [{k: r.get(k) for k in ("quantity", "value", "unit")} for r in reduced]
                        except (ValueError, TypeError, KeyError) as exc:
                            details["reduction_error"] = str(exc)
                if quantity == "sps_log" and isinstance(obs.get("value"), dict):
                    details["processing_record"] = {"method": obs["value"].get("method"),
                        "sample_count": len(obs["value"].get("time_s", [])), "reduction": obs["value"].get("reduction"),
                        "limits": obs["value"].get("limits"), "raw_records": "read_evidence or compute payload.evidence using this evidence_id"}
                target["observations"].append(details)
            if quantity in UNITS:
                # Preserve originals above, but disable Gaussian scoring in the
                # diagnostic copy; numeric sd never implies a distribution.
                check_record = copy.deepcopy(record)
                for s in check_record["request"]["specimens"]:
                    s["measurements"] = [quantity] if s["specimen_id"] == sid else []
                for prediction in check_record["prediction"]["predictions"]:
                    for value in prediction.values():
                        if isinstance(value, dict) and "sd" in value:
                            value["sd"] = None
                check_rows = copy.deepcopy(matching)
                for obs in check_rows:
                    if item and item.get("unit") != obs.get("unit"):
                        obs["status"] = "invalid"  # diagnostic exclusion only, original retained
                try:
                    checked = evaluate_fresh_predictions(check_record, check_rows, quantities=[quantity], allow_omitted_forecasts=True)
                    target.update(checked["fixed_targets"][0])
                    target.update(residuals=checked["diagnostics"]["residuals"], exclusions=checked["excluded"],
                                  genealogy=checked["genealogy"], timing=checked["timing"],
                                  history_conflicts=checked["history_conflicts"])
                    for exclusion in target["exclusions"]:
                        observed = next((o for o in matching if o["evidence_id"] == exclusion["evidence_id"]), {})
                        if item and item.get("unit") != observed.get("unit"):
                            exclusion["reason"] = "unit_mismatch"
                except (ValueError, TypeError, KeyError) as exc:
                    target["diagnostic_error"] = str(exc)
                    report["diagnostic_errors"].append({"specimen_id": sid, "quantity": quantity, "error": str(exc)})
            report["targets"].append(target)
    report["counts"] = {"requested_targets": len(report["targets"]),
        "forecast_states": dict(Counter(t["forecast_state"] for t in report["targets"] if t["quantity"] in UNITS)),
        "measurement_states": dict(Counter(t["measurement_state"] for t in report["targets"]))}
    report["genealogy"] = {"requested_bodies": len(record["request"]["specimens"]),
        "requested_preparations": len({s["preparation_id"] for s in record["request"]["specimens"]}),
        "distinct_observed_specimen_ids": len({r["specimen_id"] for r in rows if r.get("specimen_id")}),
        "non_specimen_observation_ids": [r["evidence_id"] for r in rows if not r.get("specimen_id")],
        "reported_actual_bodies": (len({r.get("actual_genealogy", {}).get("specimen_id") for r in rows
                                        if r.get("actual_genealogy", {}).get("specimen_id")})
                                   if any(r.get("actual_genealogy", {}).get("specimen_id") for r in rows) else None),
        "reported_preparations": len({r.get("preparation_id") for r in rows if r.get("preparation_id")}),
        "independence_verified": False,
        "limit": "shared preparations and repeated fields are not independent manufacture; distinct identities alone do not verify independence"}
    report["limits"] = ["Public released records only; no hidden explanation or suggested experiment",
        "Requested endpoints and predictions remain frozen; delivered-condition differences are not silently refitted",
        "No Gaussian calibration inference from scenario widths, specimen scatter or undeclared sd",
        "A reduction reproduces arithmetic, not calibration, representativeness or pore-access assumptions",
        "Receipt chronology does not prove physical execution chronology"]
    return report
